/* From Uiverse.io by gouthamnetha02  - Tags: tooltip, red, hover, color, hover effect, css, css effect */
.__UIV_SCOPE__ .tooltip {
  position: relative;
  display: inline-block;
  cursor: pointer;
}

.__UIV_SCOPE__ .tooltip button {
  background-color: #db3434;
  color: #fff;
  border: none;
  padding: 10px 20px;
  border-radius: 5px;
  font-size: 16px;
  cursor: pointer;
  transition: background-color 0.3s, transform 0.2s ease-out;
}

.__UIV_SCOPE__ .tooltip button:hover {
  background-color: #b92929;
  transform: scale(1.05);
}

.__UIV_SCOPE__ .tooltip:hover .tooltiptext {
  visibility: visible;
  opacity: 1;
}

.__UIV_SCOPE__ .tooltiptext {
  visibility: hidden;
  width: 160px;
  background-color: #333;
  color: #fff;
  text-align: center;
  border-radius: 8px;
  padding: 5px;
  position: absolute;
  z-index: 1;
  bottom: 125%;
  left: 50%;
  margin-left: -80px;
  opacity: 0;
  transition: opacity 0.3s;
}

.__UIV_SCOPE__ .tooltiptext::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 50%;
  margin-left: -5px;
  border-width: 5px;
  border-style: solid;
  border-color: #333 transparent transparent transparent;
}
